/**
 * Utilidades para los tests generados de las features: dobles de los repositorios y de los servicios de
 * interacción (diálogos, avisos, tareas largas), para probar cada clase sin backend ni plantilla.
 *
 * Solo lo importan los `*.spec.ts`: no forma parte del build de la aplicación.
 */

/** Doble de un `Tick`/`Shift`: una señal con `fetch`, `reset` y `next` espiados; `set` fija su valor. */
export interface TickMock<T = any> {
  (): T | undefined;
  set(value: T | undefined): void;
  searching: WritableSignal<boolean>;
  fetch: jasmine.Spy;
  reset: jasmine.Spy;
  next: jasmine.Spy;
  subscribe: jasmine.Spy;
}

export function mockTick<T = any>(value?: T): TickMock<T> {
  const state = signal<T | undefined>(value);
  const tick = (() => state()) as TickMock<T>;
  tick.set = (next) => state.set(next);
  tick.searching = signal(false);
  tick.fetch = jasmine.createSpy('fetch').and.callFake(() => tick);
  tick.reset = jasmine.createSpy('reset').and.callFake(() => tick);
  tick.next = jasmine.createSpy('next').and.callFake(() => tick);
  tick.subscribe = jasmine.createSpy('subscribe');
  return tick;
}

/**
 * Doble de un repositorio generado: los métodos conocidos devuelven valores neutros y cualquier otro se crea al
 * usarlo como espía que emite `undefined`. `aclTick` y `contextSignal` permiten fijar el ACL y el contexto.
 */
export type RepositoryMock = { [method: string]: jasmine.Spy } & {
  readonly aclTick: TickMock<{ generic: Acl; specific: Acl }>;
  readonly contextSignal: WritableSignal<ContextFields>;
};

export function mockRepository(name = 'repository'): RepositoryMock {
  const aclTick = mockTick<{ generic: Acl; specific: Acl }>();
  const contextSignal = signal<ContextFields>({ fixed: {}, defaults: {}, filtered: [] });
  const spy = (method: string) => jasmine.createSpy(`${name}.${method}`);
  const known: Record<string | symbol, any> = {
    aclTick,
    contextSignal,
    acl: spy('acl').and.returnValue(aclTick),
    context: spy('context').and.returnValue(contextSignal),
    projection: spy('projection').and.callFake(() => mockTick()),
    projections: spy('projections').and.callFake(() => mockTick()),
    checkAcl: spy('checkAcl').and.returnValue(of({})),
    canDeleteSelection: spy('canDeleteSelection').and.returnValue(true),
    generateComb: spy('generateComb').and.returnValue('generated-key'),
    values: spy('values').and.returnValue(of([])),
    list: spy('list').and.returnValue(of({ content: [], hasNext: false, next: null })),
    retrieve: spy('retrieve').and.returnValue(of(undefined)),
    displayProvider: spy('displayProvider').and.returnValue({ display: (item: any) => String(item?.name ?? '') }),
    selectorProvider: spy('selectorProvider').and.callFake(() => ({
      search: () => of([]),
      display: (item: any) => String(item?.name ?? ''),
      value: (item: any) => item,
      select: () => of(undefined),
      equals: (one: any, other: any) => one === other,
    })),
  };
  return new Proxy(known, {
    get(target, prop) {
      // Ni promesa ni serializable: no inventar `then`/`toJSON`
      if (typeof prop === 'symbol' || prop === 'then' || prop === 'toJSON' || prop in target) {
        return target[prop];
      }
      target[prop] = spy(prop).and.returnValue(of(undefined));
      return target[prop];
    },
  }) as RepositoryMock;
}

/** Doble de `RepositoryStore`: el provider tal cual, sin caché persistente ni contextos. */
export function mockRepositoryStore(): any {
  return {
    provider: (meta: any) => meta.provider,
    of: () => ({}),
    ttl: () => 0,
    contexts: signal([]),
  };
}

/** Da los permisos indicados en el ACL genérico (y en el específico) del repositorio. */
export function allow(repository: RepositoryMock, ...permissions: string[]): void {
  const acl: Acl = { allows: permissions.map((name) => ({ name, allowed: true })) } as Acl;
  repository.aclTick.set({ generic: acl, specific: acl });
}

/** Doble del contenedor de acciones: `close` y la selección espiados. */
export function mockContainer(): any {
  return {
    close: jasmine.createSpy('close'),
    selectionModel: jasmine.createSpyObj('SelectionModel', ['clearSelection']),
  };
}

/** Dobles de los servicios de interacción que usan las acciones. */
export interface InteractionMocks {
  confirm: jasmine.SpyObj<ConfirmDialogService>;
  params: jasmine.SpyObj<ActionParamsDialogService>;
  notify: jasmine.SpyObj<NotifyService>;
  longTask: jasmine.SpyObj<LongTaskService>;
  dialog: jasmine.SpyObj<MatDialog>;
  conflicts: jasmine.SpyObj<EditConflictService>;
}

export function mockInteractions(): InteractionMocks {
  const confirm = jasmine.createSpyObj<ConfirmDialogService>('ConfirmDialogService', ['confirm']);
  confirm.confirm.and.returnValue(of(true));
  const params = jasmine.createSpyObj<ActionParamsDialogService>('ActionParamsDialogService', ['ask']);
  params.ask.and.returnValue(of({}));
  const notify = jasmine.createSpyObj<NotifyService>('NotifyService', ['success', 'error', 'info']);
  const longTask = jasmine.createSpyObj<LongTaskService>('LongTaskService', ['run']);
  // Suscribe al progreso para que la tarea se ejecute de verdad
  longTask.run.and.callFake((_title, progress) => {
    progress.subscribe({ error: () => undefined });
    return of(undefined);
  });
  const dialog = jasmine.createSpyObj<MatDialog>('MatDialog', ['open']);
  dialog.open.and.returnValue({ afterClosed: () => of(undefined) } as any);
  const conflicts = jasmine.createSpyObj<EditConflictService>('EditConflictService', ['save']);
  conflicts.save.and.callFake((request: any) => request.save(request.value, request.original));
  return { confirm, params, notify, longTask, dialog, conflicts };
}

export interface FeatureTestingOptions {
  /** Clase y doble de cada repositorio que se sustituye. */
  repositories?: [Type<any>, RepositoryMock][];
  interactions?: InteractionMocks;
  imports?: any[];
  declarations?: Type<any>[];
  providers?: (Provider | EnvironmentProviders)[];
  /** Textos por idioma y scope (`{ en: {...}, 'entity/scope/en': {...} }`); por defecto, ninguno. */
  langs?: Record<string, any>;
}

/** Configura TestBed para una clase generada: transloco sin textos, repositorios y servicios de interacción falsos. */
export function configureFeatureTesting(options: FeatureTestingOptions = {}): InteractionMocks {
  const interactions = options.interactions ?? mockInteractions();
  TestBed.configureTestingModule({
    declarations: options.declarations ?? [],
    imports: [
      TranslocoTestingModule.forRoot({
        langs: { en: {}, ...(options.langs ?? {}) },
        translocoConfig: { availableLangs: ['en'], defaultLang: 'en' },
      }),
      ...(options.imports ?? []),
    ],
    providers: [
      ...(options.repositories ?? []).map(([type, mock]) => ({ provide: type, useValue: mock })),
      { provide: ConfirmDialogService, useValue: interactions.confirm },
      { provide: ActionParamsDialogService, useValue: interactions.params },
      { provide: NotifyService, useValue: interactions.notify },
      { provide: LongTaskService, useValue: interactions.longTask },
      { provide: MatDialog, useValue: interactions.dialog },
      { provide: EditConflictService, useValue: interactions.conflicts },
      ...(options.providers ?? []),
    ],
  });
  return interactions;
}

/** Crea el componente sin su plantilla: los tests generados prueban la lógica de la clase. */
export function createWithoutTemplate<T>(type: Type<T>, inputs: Record<string, unknown> = {}): ComponentFixture<T> {
  TestBed.overrideTemplate(type, '');
  const fixture = TestBed.createComponent(type);
  Object.entries(inputs).forEach(([name, value]) => fixture.componentRef.setInput(name, value));
  fixture.detectChanges();
  return fixture;
}

/** Comprueba que un NgModule generado compila con sus dependencias reales y se puede instanciar. */
export function moduleCompiles(module: Type<any>, options: FeatureTestingOptions = {}): void {
  configureFeatureTesting({ ...options, imports: [module, ...(options.imports ?? [])] });
  expect(TestBed.inject(module)).toBeTruthy();
}

/** Acceso a miembros protegidos desde un test. */
export function internals<T = any>(target: unknown): T {
  return target as T;
}
